module @_QMshapes {

  // Dispatch tables — one per type with bound procedures
  fir.dispatch_table @_QDTshapesTShape {
    fir.dt_entry area,      @_QPshape_area
    fir.dt_entry perimeter, @_QPshape_perimeter
  }
  fir.dispatch_table @_QDTshapesTCircle extends @_QDTshapesTShape {
    fir.dt_entry area,      @_QPcircle_area      // override
    fir.dt_entry perimeter, @_QPcircle_perimeter // override
  }
  fir.dispatch_table @_QDTshapesTRectangle extends @_QDTshapesTShape {
    fir.dt_entry area,      @_QPrect_area
    fir.dt_entry perimeter, @_QPrect_perimeter
  }

  func.func @_QPprint_shape_info(
      %arg0: !fir.class<!fir.type<@_QTshapesTShape>> {fir.bindc_name = "s", fir.in}
  ) {
    // Dynamic dispatch: fir.dispatch looks up method in vtable
    %a   = fir.dispatch "area"(%arg0 : !fir.class<!fir.type<@_QTshapesTShape>>) -> f32
    %per = fir.dispatch "perimeter"(%arg0 : !fir.class<!fir.type<@_QTshapesTShape>>) -> f32

    // SELECT TYPE → runtime type descriptor comparisons
    %is_circle = fir.is_present_and_same_type_as
                   %arg0, @_QDTshapesTCircle : (!fir.class<...>, !fir.dispatch_table) -> i1

    fir.if %is_circle {
      // TYPE IS (Circle) block — s%radius accessible with concrete type
      %circle_ref = fir.convert %arg0 : (!fir.class<...>) -> !fir.ref<!fir.type<@_QTshapesTCircle>>
      %r_idx      = fir.field_index radius, !fir.type<@_QTshapesTCircle>
      %r_ptr      = fir.coordinate_of %circle_ref, %r_idx : (...) -> !fir.ref<f32>
      %radius     = fir.load %r_ptr : !fir.ref<f32>
      // ... print
    }

    %is_rect = fir.is_present_and_same_type_as
                 %arg0, @_QDTshapesTRectangle : (!fir.class<...>, !fir.dispatch_table) -> i1
    fir.if %is_rect {
      // TYPE IS (Rectangle) block
      %rect_ref = fir.convert %arg0 : (!fir.class<...>) -> !fir.ref<!fir.type<@_QTshapesTRectangle>>
      // ... access s%width, s%height
    }
    // CLASS DEFAULT handled by fall-through
    return
  }
}
